from collections import deque
out=[row[:] for row in grid]
no=[]
for r in range(30):
 for c in range(30):
  if grid[r][c]!=6: continue
  q=deque([(r,c)]); seen={(r,c)}; vals=[]
  while q:
   i,j=q.popleft()
   if grid[i][j]!=6: vals.append(grid[i][j])
   for p in [(j,i)]+([ (31-i,j) ] if 2<=i<=29 else []):
    if 0<=p[0]<30 and 0<=p[1]<30 and p not in seen:
     seen.add(p); q.append(p)
  if not vals: no.append((r,c,seen))
  elif len(set(vals))>1: print('conflict',r,c,set(vals))
  else: out[r][c]=vals[0]
len(no), no[:5],len(out), set(map(len,out))
